import {
    BooleanColumn,
    IntegerColumn,
    ReferenceColumn,
    ScriptColumn,
    StringColumn,
    Table,
    TranslatedTextColumn,
    UserRolesColumn,
} from '../../db'

export const sp_instance = Table({
    name: 'sp_instance',
    extends: 'sys_metadata',
    display: 'title',
    schema: {
        active: BooleanColumn({ label: 'Active', default: true }),
        class_name: StringColumn({ label: 'Bootstrap class name' }),
        color: StringColumn({
            label: 'Bootstrap color',
            default: 'default',
            choices: {
                default: { label: 'Default' },
                warning: { label: 'Warning' },
                primary: { label: 'Primary' },
                danger: { label: 'Danger' },
                success: { label: 'Success' },
                info: { label: 'Info' },
            },
        }),
        css: StringColumn({ label: 'CSS' }),
        glyph: StringColumn({ label: 'Glyph' }),
        id: StringColumn({}),
        order: IntegerColumn({ label: 'Order', default: 1 }),
        roles: UserRolesColumn({ label: 'Roles' }),
        short_description: TranslatedTextColumn({ label: 'Short description' }),
        size: StringColumn({
            label: 'Bootstrap size',
            default: 'md',
            choices: {
                sm: { label: 'Small' },
                md: { label: 'Medium' },
                lg: { label: 'Large' },
                xs: { label: 'Extra Small' },
            },
        }),
        sp_column: ReferenceColumn({ label: 'Column', referenceTable: 'sp_column' }),
        sp_widget: ReferenceColumn({ label: 'Widget', referenceTable: 'sp_widget' }),
        title: TranslatedTextColumn({ label: 'Title' }),
        url: StringColumn({ label: 'HREF / URL' }),
        widget_parameters: ScriptColumn({ label: 'Additional options, JSON format' }),
    },
})
